/**
 * Validates the incoming request payload for an API call in the transaction flow.
 * 
 * @param {Object} targetPayload - The incoming request payload to validate.
 * @param {Object} sessionData - Data collected from previous transaction steps.
 * 
 * @returns {Object} { valid: boolean, code: number, description: string }
 */
function validate(targetPayload, sessionData) {

	if (!targetPayload?.context) {
		return {
			valid: false,
			code: 400,
			description: "context is required"
		};
	}

	if (targetPayload.context.action !== "search") {
		return {
			valid: false,
			code: 400,
			description: "context.action should be search"
		};
	}

	if (targetPayload.context.domain !== "ONDC:TRV11") {
		return {
			valid: false,
			code: 400,
			description: "Invalid domain"
		};
	}

	if (targetPayload.context.version !== "2.0.1") {
		return {
			valid: false,
			code: 400,
			description: "Invalid version"
		};
	}

	if (!targetPayload?.message?.intent) {
		return {
			valid: false,
			code: 400,
			description: "message.intent is required"
		};
	}

	if (
		targetPayload?.message?.intent?.fulfillment?.vehicle?.category !== "BUS"
	) {
		return {
			valid: false,
			code: 400,
			description: "vehicle category should be BUS"
		};
	}

	if (
		targetPayload?.message?.intent?.payment?.collected_by !== "BAP"
	) {
		return {
			valid: false,
			code: 400,
			description: "payment.collected_by should be BAP"
		};
	}

	const tags = targetPayload?.message?.intent?.payment?.tags;

	if (!Array.isArray(tags) || tags.length === 0) {
		return {
			valid: false,
			code: 400,
			description: "payment.tags should be a non-empty array"
		};
	}

	const buyerFinderFees = tags.find(
		(tag) => tag?.descriptor?.code === "BUYER_FINDER_FEES"
	);

	if (!buyerFinderFees) {
		return {
			valid: false,
			code: 400,
			description: "BUYER_FINDER_FEES tag is missing"
		};
	}

	const buyerFeePercentage = buyerFinderFees?.list?.find(
		(item) =>
			item?.descriptor?.code === "BUYER_FINDER_FEES_PERCENTAGE"
	);

	if (!buyerFeePercentage) {
		return {
			valid: false,
			code: 400,
			description: "BUYER_FINDER_FEES_PERCENTAGE is missing"
		};
	}

	const settlementTerms = tags.find(
		(tag) => tag?.descriptor?.code === "SETTLEMENT_TERMS"
	);

	if (!settlementTerms) {
		return {
			valid: false,
			code: 400,
			description: "SETTLEMENT_TERMS tag is missing"
		};
	}

	const delayInterest = settlementTerms?.list?.find(
		(item) => item?.descriptor?.code === "DELAY_INTEREST"
	);

	if (!delayInterest) {
		return {
			valid: false,
			code: 400,
			description: "DELAY_INTEREST is missing"
		};
	}

	const staticTerms = settlementTerms?.list?.find(
		(item) => item?.descriptor?.code === "STATIC_TERMS"
	);

	if (!staticTerms) {
		return {
			valid: false,
			code: 400,
			description: "STATIC_TERMS is missing"
		};
	}

	return {
		valid: true,
		code: 200,
		description: "Valid request"
	};
}

