	if (!Array.isArray(tags) || tags.length === 0) {
		return {
			valid: false,
			code: 400,
			description: "payment.tags should be a non-empty array"
		};
	}

	const buyerFinderFees = tags.find(
		(tag) => tag?.descriptor?.code === "BUYER_FINDER_FEES"
	);

	if (!buyerFinderFees) {
		return {
			valid: false,
			code: 400,
			description: "BUYER_FINDER_FEES tag is missing"
		};
	}

	const buyerFeePercentage = buyerFinderFees?.list?.find(
		(item) =>
			item?.descriptor?.code === "BUYER_FINDER_FEES_PERCENTAGE"
	);

	if (!buyerFeePercentage) {
		return {
			valid: false,
			code: 400,
			description: "BUYER_FINDER_FEES_PERCENTAGE is missing"
		};
	}

	const settlementTerms = tags.find(
		(tag) => tag?.descriptor?.code === "SETTLEMENT_TERMS"
	);

	if (!settlementTerms) {
		return {
			valid: false,
			code: 400,
			description: "SETTLEMENT_TERMS tag is missing"
		};
	}

	const delayInterest = settlementTerms?.list?.find(
		(item) => item?.descriptor?.code === "DELAY_INTEREST"
	);

	if (!delayInterest) {
		return {
			valid: false,
			code: 400,
			description: "DELAY_INTEREST is missing"
		};
	}

	const staticTerms = settlementTerms?.list?.find(
		(item) => item?.descriptor?.code === "STATIC_TERMS"
	);

	if (!staticTerms) {
		return {
			valid: false,
			code: 400,
			description: "STATIC_TERMS is missing"
		};
	}

	return {
		valid: true,
		code: 200,
		description: "Valid request"
	};
}

