  const userInput=sessionData?.user_inputs;
  existingPayload.context.location.city.code=userInput?.city_code;
  existingPayload.context.bpp_id =userInput?.bpp_id;
  existingPayload.context.bpp_uri =userInput?.bpp_uri;
  existingPayload.message.intent.fulfillment.vehicle.category =
  userInput?.vehicle_category;

  existingPayload.message.intent.payment.collected_by = userInput?.payment_type;
  existingPayload.message.intent.fulfillment.stops.forEach((stop) => {
