/**
 * Validates the incoming search intent payload.
 * 
 * @param {Object} targetPayload - Incoming payload
 * @param {Object} sessionData - Session data
 * 
 * @returns {Object} Validation result
 */
function validate(targetPayload, sessionData) {
	const intent =
		targetPayload?.message?.intent;

	if (!intent) {
		return {
			valid: false,
			code: 400,
			description: "Missing message.intent",
		};
	}

	const vehicleCategory =
		intent?.fulfillment?.vehicle?.category;

	if (vehicleCategory !== "METRO") {
		return {
			valid: false,
			code: 400,
			description:
				"vehicle.category must be METRO",
		};
	}

	const payment = intent?.payment;

	if (!payment) {
		return {
			valid: false,
			code: 400,
			description: "Missing payment",
		};
	}

	if (payment?.collected_by !== "BAP") {
		return {
			valid: false,
			code: 400,
			description:
				"payment.collected_by must be BAP",
		};
	}

	const requiredTags = [
		"BUYER_FINDER_FEES",
		"SETTLEMENT_TERMS",
	];

	for (const code of requiredTags) {
		const tagExists = payment?.tags?.some(
			(tag) =>
				tag?.descriptor?.code === code
		);

		if (!tagExists) {
			return {
				valid: false,
				code: 400,
				description:
					`Missing payment tag ${code}`,
			};
		}
	}

	return {
		valid: true,
		code: 200,
		description: "Valid request",
	};
}

