 * This function allows customization of the default payload using session data
 * from previous steps and user inputs.
 * 
 * @param {Object} defaultPayload - The base payload object with context already populated.
 * @param {Object} sessionData - Data collected from previous transaction steps.
 * @param {Object} sessionData.user_inputs - User-provided input values for this step.
 * @param {*} sessionData.[key] - Any saved data from previous steps (defined in saveData config).
 * 
 * @returns {Object} The generated payload object to be sent in the API request.
 */
async function generate(existingPayload, sessionData) {
  const userInput=sessionData?.user_inputs;
  existingPayload.context.location.city.code=userInput?.city_code;
  return existingPayload;
}

/**
 * Validates the incoming search intent payload.
 * 
 * @param {Object} targetPayload - Incoming payload
 * @param {Object} sessionData - Session data
 * 
 * @returns {Object} Validation result
 */
function validate(targetPayload, sessionData) {
	const intent =
		targetPayload?.message?.intent;

	if (!intent) {
		return {
			valid: false,
			code: 400,
			description: "Missing message.intent",
		};
	}

	const vehicleCategory =
		intent?.fulfillment?.vehicle?.category;

	if (vehicleCategory !== "METRO") {
		return {
			valid: false,
			code: 400,
			description:
				"vehicle.category must be METRO",
		};
	}

	const payment = intent?.payment;

	if (!payment) {
		return {
			valid: false,
			code: 400,
			description: "Missing payment",
		};
	}

	if (payment?.collected_by !== "BAP") {
		return {
			valid: false,
			code: 400,
			description:
				"payment.collected_by must be BAP",
		};
	}

	const requiredTags = [
		"BUYER_FINDER_FEES",
		"SETTLEMENT_TERMS",
	];

	for (const code of requiredTags) {
		const tagExists = payment?.tags?.some(
			(tag) =>
				tag?.descriptor?.code === code
		);

		if (!tagExists) {
			return {
				valid: false,
				code: 400,
				description:
					`Missing payment tag ${code}`,
			};
		}
	}

	return {
		valid: true,
		code: 200,
		description: "Valid request",
	};
}

/**
 * Checks if the requirements for proceeding with the API call are met.
 * 
 * @param {Object} sessionData - Data collected from previous transaction steps.
 * 
 * @returns {Object} { valid: boolean, code: number, description: string }
 */
function meetsRequirements(sessionData) {
  return { valid: true, code: 200, description: "Requirements met" };
}

