		};
	}

	const requiredTags = [
		"BUYER_FINDER_FEES",
		"SETTLEMENT_TERMS",
	];

	for (const code of requiredTags) {
		const tagExists = payment?.tags?.some(
			(tag) =>
				tag?.descriptor?.code === code
		);

		if (!tagExists) {
			return {
				valid: false,
				code: 400,
				description:
					`Missing payment tag ${code}`,
			};
		}
	}

	return {
		valid: true,
		code: 200,
		description: "Valid request",
	};
